    ('60000000-0000-0000-0000-000000000009','Leo Tolstoy','tolstoy@example.com','07000010009',NULL,'Epic novelist of War and Peace, exploring human nature.','41000000-0000-0000-0000-000000000001','41000000-0000-0000-0000-000000000001','active',7,v_ts,v_ts,'00000000-0000-0000-0000-111000000001'),
