    ('60000000-0000-0000-0000-000000000012','James Joyce','joyce@example.com','07000010012',NULL,'Known for Ulysses, experimental narrative style.','41000000-0000-0000-0000-000000000001','41000000-0000-0000-0000-000000000001','inactive',7,v_ts,v_ts,'00000000-0000-0000-0000-111000000001'),
    ('60000000-0000-0000-0000-000000000013','Isaac Newton','isaac.newton@example.com','07000010013',NULL,'Formulated the laws of motion and universal gravitation, laying the groundwork for classical physics.','41000000-0000-0000-0000-000000000002','41000000-0000-0000-0000-000000000002','inactive',7,v_ts,v_ts,'00000000-0000-0000-0000-111000000002'),
    ('60000000-0000-0000-0000-000000000014','Marie Curie','marie.curie@example.com','07000010014',NULL,'Pioneer of radioactivity and first woman to win a Nobel Prize, she advanced both science and women’s rights.','41000000-0000-0000-0000-000000000002','41000000-0000-0000-0000-000000000002','inactive',7,v_ts,v_ts,'00000000-0000-0000-0000-111000000002'),
