    ('60000000-0000-0000-0000-000000000016','Michelangelo','michelangelo@example.com','07000010016',NULL,'Master sculptor of David and painter of the Sistine Chapel ceiling, he defined Renaissance artistry.','41000000-0000-0000-0000-000000000002','41000000-0000-0000-0000-000000000002','inactive',7,v_ts,v_ts,'00000000-0000-0000-0000-111000000002'),
    ('60000000-0000-0000-0000-000000000017','Johann Wolfgang von Goethe','goethe@example.com','07000010017',NULL,'German writer and statesman, his “Faust” remains a cornerstone of world literature.','41000000-0000-0000-0000-000000000002','41000000-0000-0000-0000-000000000002','inactive',7,v_ts,v_ts,'00000000-0000-0000-0000-111000000002'),
    ('60000000-0000-0000-0000-000000000018','Emily Brontë','emily.bronte@example.com','07000010018',NULL,'Author of Wuthering Heights, her work explored passion, isolation, and the natural world.','41000000-0000-0000-0000-000000000002','41000000-0000-0000-0000-000000000002','inactive',7,v_ts,v_ts,'00000000-0000-0000-0000-111000000002'),
    ('60000000-0000-0000-0000-000000000019','Edgar Allan Poe','edgar.poe@example.com','07000010019',NULL,'Father of the short story and detective fiction, he delved into the macabre and the mind.','41000000-0000-0000-0000-000000000002','41000000-0000-0000-0000-000000000002','inactive',7,v_ts,v_ts,'00000000-0000-0000-0000-111000000002'),
