    ('60000000-0000-0000-0000-000000000028','Alexander the Great','alexander.thegreat@example.com','07000010028',NULL,'King of Macedon who created one of the largest empires of the ancient world.','41000000-0000-0000-0000-000000000003','41000000-0000-0000-0000-000000000003','inactive',7,v_ts,v_ts,'00000000-0000-0000-0000-111000000001'),
